const message = $json.message || {};
const text = String(message.text || "").trim();
const normalized = text.toLowerCase();
const chatId = message.chat?.id || "";

const store = $getWorkflowStaticData("global");
const chatKey = "chat_" + chatId;
const hasPendingReceipt = Boolean(store[chatKey]?.pendingReceipt);

const startsWithReceipt = /^\/?receipt\b:?/.test(normalized);
const receiptBody = startsWithReceipt
  ? normalized.replace(/^\/?receipt\b:?\s*/, "").trim()
  : "";

const isFullReceipt = startsWithReceipt && receiptBody.length > 0;
const isReceiptRequest = normalized === "receipt" || normalized === "/receipt";
const isReceiptDates = !startsWithReceipt && hasPendingReceipt && /\bto\b/i.test(text);

return [{
  json: {
    route: isFullReceipt
      ? "full_receipt"
      : isReceiptRequest
        ? "receipt_request"
        : isReceiptDates
          ? "receipt_dates"
          : "tracker",
    isFullReceipt,
    isReceiptRequest,
    isReceiptDates,
    text,
    chatId,
    fromId: message.from?.id || "",
    firstName: message.from?.first_name || "",
    username: message.from?.username || message.chat?.username || "",
    message_text: text,
    chat_id: chatId,
    telegram_user: message.from?.username || message.chat?.username || "",
    message_date: new Date().toISOString(),
    message
  }
}];

const text = $json.message_text || $json.message?.text || "";

// Accepts:
// /receipt John Doe, Kilimani Studio, 10 Jun 2026 to 14 Jun 2026, KES 24000, M-Pesa QH123ABC
// /Receipt: John Doe, Kilimani Studio, 10 Jun 2026 to 14 Jun 2026, KES 24000, M-Pesa QH123ABC
// Receipt: John Doe, Kilimani Studio, 10 Jun 2026 to 14 Jun 2026, KES 24000, M-Pesa QH123ABC

const cleaned = text
  .replace(/^\/receipt:?\s*/i, "")
  .replace(/^receipt:\s*/i, "")
  .trim();

const parts = cleaned.split(",").map(p => p.trim()).filter(Boolean);

if (parts.length < 5) {
  throw new Error("Receipt message format is incomplete. Use: /receipt Client Name, Property Name, 10 Jun 2026 to 14 Jun 2026, KES 24000, M-Pesa QH123ABC");
}

const clientName = parts[0];
const propertyName = parts[1];
const stayText = parts[2];
const amountText = parts[3];
const paymentText = parts.slice(4).join(", ");

const stayMatch = stayText.match(/^(.+?)\s+to\s+(.+)$/i);
if (!stayMatch) {
  throw new Error("Could not read stay dates. Use: 10 Jun 2026 to 14 Jun 2026");
}

const amountMatch = amountText.match(/^([A-Z]{3})\s*([\d,]+(?:\.\d{1,2})?)$/i);
if (!amountMatch) {
  throw new Error("Could not read amount. Use: KES 24000");
}

const paymentMatch = paymentText.match(/^(.+?)\s+([A-Za-z0-9-]+)$/);
if (!paymentMatch) {
  throw new Error("Could not read payment method and transaction ID. Use: M-Pesa QH123ABC");
}

const checkIn = new Date(stayMatch[1]);
const checkOut = new Date(stayMatch[2]);

if (Number.isNaN(checkIn.getTime()) || Number.isNaN(checkOut.getTime())) {
  throw new Error("Could not parse check-in/check-out dates.");
}

const nights = Math.round((checkOut - checkIn) / (1000 * 60 * 60 * 24));

if (nights <= 0) {
  throw new Error("Check-out date must be after check-in date.");
}

const receiptDate = new Date();

function toDateOnly(d) {
  return d.toISOString().slice(0, 10);
}

return {
  json: {
    chat_id: $json.chat_id || $json.message?.chat?.id || $json.id,
    message_text: $json.message_text || $json.message?.text || "",
    telegram_user: $json.telegram_user || $json.message?.from?.username || $json.username || "",
    message_date: $json.message_date || $json.date || "",
    client_name: clientName,
    property_name: propertyName,
    check_in: toDateOnly(checkIn),
    check_out: toDateOnly(checkOut),
    nights,
    currency: amountMatch[1].toUpperCase(),
    amount_paid: Number(amountMatch[2].replace(/,/g, "")),
    payment_method: paymentMatch[1],
    transaction_id: paymentMatch[2],
    receipt_date: toDateOnly(receiptDate)
  }
};

