const chatId = $json.chatId || $json.chat_id || "";
const store = $getWorkflowStaticData("global");
const chatKey = "chat_" + chatId;
const lastPayment = store[chatKey]?.lastPayment;

if (!lastPayment) {
  return [{
    json: {
      ...$json,
      hasLastPayment: false,
      errorMessage: "I do not have a saved payment for this chat yet. Send the M-Pesa payment first, or use the full /receipt command."
    }
  }];
}

store[chatKey] = store[chatKey] || {};
store[chatKey].pendingReceipt = {
  ...lastPayment,
  requestedAt: new Date().toISOString()
};

return [{
  json: {
    ...$json,
    hasLastPayment: true,
    pendingReceipt: store[chatKey].pendingReceipt
  }
}];

function dateOnly(d) {
  return d.toISOString().slice(0, 10);
}

const chatId = $json.chatId || $json.chat_id || "";
const store = $getWorkflowStaticData("global");
const chatKey = "chat_" + chatId;
const pending = store[chatKey]?.pendingReceipt;

if (!pending) {
  return [{
    json: {
      ...$json,
      receiptDetailsValid: false,
      errorMessage: "I do not have a pending receipt payment. Reply receipt after saving a payment first."
    }
  }];
}

let text = String($json.text || $json.message_text || "").trim();
let propertyOverride = "";

const commaParts = text.split(",").map(part => part.trim()).filter(Boolean);
if (commaParts.length >= 2 && /^(le royal|royal)$/i.test(commaParts[0])) {
  propertyOverride = commaParts[0].replace(/\b\w/g, char => char.toUpperCase());
  text = commaParts.slice(1).join(", ");
}

const stayMatch = text.match(/^(.+?)\s+to\s+(.+)$/i);
if (!stayMatch) {
  return [{
    json: {
      ...$json,
      receiptDetailsValid: false,
      errorMessage: "I could not read the stay dates. Send them like: 24 Jun 2026 to 28 Jun 2026"
    }
  }];
}

const checkIn = new Date(stayMatch[1]);
const checkOut = new Date(stayMatch[2]);

if (Number.isNaN(checkIn.getTime()) || Number.isNaN(checkOut.getTime())) {
  return [{
    json: {
      ...$json,
      receiptDetailsValid: false,
      errorMessage: "I could not parse those dates. Use this format: 24 Jun 2026 to 28 Jun 2026"
    }
  }];
}

const nights = Math.round((checkOut - checkIn) / (1000 * 60 * 60 * 24));
if (nights <= 0) {
  return [{
    json: {
      ...$json,
      receiptDetailsValid: false,
      errorMessage: "Check-out must be after check-in."
    }
  }];
}

delete store[chatKey].pendingReceipt;

return [{
  json: {
    chat_id: chatId,
    message_text: $json.text || "",
    telegram_user: $json.telegram_user || "",
    message_date: new Date().toISOString(),
    client_name: pending.senderName || "Guest",
    property_name: propertyOverride || pending.property || "",
    check_in: dateOnly(checkIn),
    check_out: dateOnly(checkOut),
    nights,
    currency: "KES",
    amount_paid: Number(pending.amount || 0),
    payment_method: "M-Pesa",
    transaction_id: pending.mpesaCode || "",
    receipt_date: dateOnly(new Date()),
    payment_date: pending.paymentDate || dateOnly(new Date()),
    receiptDetailsValid: true
  }
}];

