const message = $json.message || {};

return [{
  json: {
    text: $json.text || message.text || "",
    chatId: $json.chatId || message.chat?.id || "",
    fromId: $json.fromId || message.from?.id || "",
    firstName: $json.firstName || message.from?.first_name || ""
  }
}];

let ai = $json;

if (Array.isArray(ai.output)) {
  ai = ai.output[0]?.content?.[0]?.text || ai.output[0]?.text || ai.output[0];
}

if (typeof ai === "string") {
  ai = ai.replace(/```json|```/g, "").trim();
  ai = JSON.parse(ai);
}

const type = String(ai.type || "unknown").toLowerCase();
const property = ai.property || "";
const sms = ai.sms || "";
const entry = ai.entry || "";
const missingFields = ai.missing_fields || [];

const isPaymentValid = type === "payment" && Boolean(sms);
const isEntryValid = (type === "cost" || type === "booking_summary") && Boolean(entry);
const valid = Boolean(type !== "unknown" && property && (isPaymentValid || isEntryValid));

return [{
  json: {
    type,
    property,
    sms,
    entry,
    confidence: ai.confidence || "",
    reply_summary: ai.reply_summary || "",
    missing_fields: Array.isArray(missingFields) ? missingFields.join(", ") : String(missingFields || ""),
    valid
  }
}];

const chatId = $("Tracker Prepare Telegram Text").item.json.chatId || "";
const type = String($json.type || "").toLowerCase();
const sms = String($json.sms || "");
const property = $json.property || "";

let receiptPrompt = false;

if (type === "payment" && sms) {
  const amountMatch = sms.match(/Ksh\s*([\d,]+(?:\.\d{1,2})?)/i);
  const codeMatch = sms.match(/^\s*([A-Z0-9]{6,})\b/);
  const senderMatch = sms.match(/from\s+(.+?)(?:\s+\d|\s+on\b)/i);
  const dateMatch = sms.match(/\bon\s+(\d{1,2}\/\d{1,2}\/\d{2,4})\b/i);

  const store = $getWorkflowStaticData("global");
  const chatKey = "chat_" + chatId;
  store[chatKey] = store[chatKey] || {};
  store[chatKey].lastPayment = {
    property,
    senderName: senderMatch?.[1]?.trim() || "Guest",
    amount: amountMatch?.[1]?.replace(/,/g, "") || "",
    mpesaCode: codeMatch?.[1] || "",
    paymentDate: dateMatch?.[1] || "",
    source: "Telegram demo",
    smsReceived: sms
  };
  receiptPrompt = true;
}

return [{
  json: {
    ...$json,
    chatId,
    receiptPrompt
  }
}];

